CREATE OR REPLACE FUNCTION public.returns_can_access_v1(p_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (auth.uid()=p_owner OR public.has_role(auth.uid(),'super_admin'::public.app_role) OR (public.is_team_member(auth.uid(),p_owner) AND (public.has_role(auth.uid(),'admin'::public.app_role) OR EXISTS(SELECT 1 FROM public.accountant_permissions ap WHERE ap.user_id=p_owner AND ap.accountant_auth_id=auth.uid() AND ap.is_active AND ap.can_process_returns)))); $$;
REVOKE ALL ON FUNCTION public.returns_can_access_v1(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.returns_can_access_v1(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.returns_guard_write_v1() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_owner uuid; v_managed boolean; BEGIN v_owner:=CASE WHEN TG_OP='DELETE' THEN OLD.user_id ELSE NEW.user_id END; IF TG_TABLE_NAME='returns' THEN v_managed:=CASE WHEN TG_OP='DELETE' THEN OLD.posting_version=1 WHEN TG_OP='INSERT' THEN NEW.posting_version=1 ELSE OLD.posting_version=1 OR NEW.posting_version=1 END; ELSE SELECT posting_version=1 INTO v_managed FROM public.returns WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.return_id ELSE NEW.return_id END; END IF; IF (v_owner='d8ddc6f2-d666-468f-85c3-f8845fb9c71c'::uuid OR COALESCE(v_managed,false)) AND COALESCE(current_setting('app.returns_command_v1',true),'')<>'on' THEN RAISE EXCEPTION 'احفظ المردود من المسار الآمن الجديد'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $patch$ DECLARE v text; old text := 'IF v_is_sales AND v_cost IS NULL AND EXISTS(SELECT 1 FROM public.company_settings s WHERE s.user_id=r.user_id AND s.costing_engine_enabled AND s.inventory_system=''perpetual'') THEN RAISE EXCEPTION ''اربط مردود البضاعة بفاتورة البيع الأصلية للتحقق من التكلفة''; END IF;'; BEGIN SELECT pg_get_functiondef('public.returns_managed_stock_v1(uuid,boolean)'::regprocedure) INTO v; IF position(old IN v)=0 THEN RAISE EXCEPTION 'Unexpected returns cost contract'; END IF; v:=replace(v,old,'IF v_is_sales AND it.source_invoice_item_id IS NULL AND EXISTS(SELECT 1 FROM public.company_settings s WHERE s.user_id=r.user_id AND s.costing_engine_enabled AND s.inventory_system=''perpetual'') THEN SELECT avg_cost INTO v_cost FROM public.inventory_cost_balances WHERE user_id=r.user_id AND product_id=it.product_id AND warehouse_id=r.warehouse_id FOR SHARE; IF COALESCE(v_cost,0)<=0 THEN RAISE EXCEPTION ''تكلفة الصنف غير متاحة للمردود الحر؛ راجع المخزون أو اربطه بالفاتورة الأصلية''; END IF; END IF;'); EXECUTE v; END $patch$;
DO $patch$ DECLARE v text; BEGIN SELECT pg_get_functiondef('public.save_return_command_v1(uuid,text,jsonb,jsonb,uuid,integer,boolean)'::regprocedure) INTO v; IF position('IF v_refund NOT IN' IN v)=0 THEN RAISE EXCEPTION 'Unexpected returns command contract'; END IF; v:=replace(v,'IF v_refund NOT IN','IF COALESCE(p_document->>''currency'',''شيكل'') NOT IN (''شيكل'',''ILS'',''₪'') THEN RAISE EXCEPTION ''مسار المردود الحالي يدعم الشيكل فقط''; END IF; IF v_refund NOT IN'); v:=replace(v,'AND status NOT IN (''draft'',''cancelled'',''void'') FOR UPDATE','AND status NOT IN (''draft'',''cancelled'',''void'') AND NOT COALESCE(is_voided,false) AND COALESCE(currency,''شيكل'') IN (''شيكل'',''ILS'',''₪'') FOR UPDATE'); EXECUTE v; END $patch$;